        r = subprocess.run(["gh", "issue", "create", "--repo", "pixelelated/distribution", "--title", t, "--label", "bug", "--milestone", "M6: Codebase renovation", "--body-file", os.path.join(OUT, pl + ".md")], capture_output=True, text=True)
